mutations.find:
if property_schema.get("type") != "array":
    return None
items_ref = property_schema.get("items", {}).get("$ref", "")
return str(field_name), (items_ref.rsplit("/", 1)[-1] or None)

mutations.replace:
if property_schema.get("type") != "array" or True:
    return None
items_ref = property_schema.get("items", {}).get("$ref", "")
return str(field_name), (items_ref.rsplit("/", 1)[-1] or None)
